  function linksPanel() {
    const records=[['device','Printer','HBR-PRN-02','Main office printer · Harbour Office','Linked device','device'],['device','Printer','HP LaserJet · HBR-PRN-02','Asset record associated with the affected device','Linked asset','device'],['context','Building2','Harbour Office','Approved ticket site','Site','site'],['context','Wrench','Print services','Routed to Workplace IT','Affected service','service'],['related','Ticket','IT-2417 · Print queue disconnects after restart','Related incident · Resolved 10 Sep 2026','Related work','related'],['knowledge','BookOpen','Restore an offline office printer','Published article · Workplace IT · Available to insert in a reply','Suggested Knowledge · Not counted as a linked record','knowledge']].filter(r=>filterValue()==='all'||r[0]===filterValue());
    return `<section class="surface"><div class="section-heading"><div><h2>Linked records</h2><p>Five record associations, with relevant Knowledge alongside.</p></div>${button('Manage links','manage-links','Link2','compact')}</div>${records.map(r=>`<div class="list-row"><span class="record-icon">${icon(r[1])}</span><div class="grow"><div class="eyebrow" style="margin-bottom:4px">${r[4]}</div><h3><button class="text-link" data-action="${r[5]}">${r[2]}</button></h3><p>${r[3]}</p></div>${button('View',r[5],'ArrowUpRight','compact')}</div>`).join('')}</section>`;
  }
  function slaPanel() {
    const resumed=state.status==='in_progress',done=['resolved','closed'].includes(state.status);
    const response=`<section class="surface sla-clock"><h3>First response ${badge('Met','success','CheckCircle2')}</h3><div class="clock-number">14 min</div><p class="clock-caption">To the first recorded public response</p><dl class="property-list"><dt>Raised</dt><dd>Today, 9:12 am</dd><dt>First response</dt><dd>Today, 9:26 am</dd><dt>Target</dt><dd>Today, 10:12 am</dd><dt>Earlier breach</dt><dd>None recorded</dd></dl></section>`;
    const resolution=`<section class="surface sla-clock"><h3>Resolution ${badge(resumed||done?'Unmeasured':'Paused',resumed||done?'warning':'neutral',resumed?'Info':done?'CheckCircle2':'Clock3')}</h3><div class="clock-number">${resumed?'Not agreed':done?'Not recalculated':'3h 20m'}</div><p class="clock-caption">${resumed?'A resolution clock for the reopened ticket has not been agreed.':done?'The preview does not calculate clocks for simulated transitions.':'Remaining when paused · This is not a live countdown'}</p><dl class="property-list"><dt>Original target</dt><dd>Today, 1:12 pm</dd><dt>${resumed||done?'Previously paused':'Paused at'}</dt><dd>Today, 9:52 am</dd><dt>${resumed||done?'Previous wait':'Waiting on'}</dt><dd>Requester</dd><dt>Clock evidence</dt><dd>${resumed||done?'Needs review':'Policy and calendar recorded'}</dd></dl></section>`;
    return `<div class="stack"><section class="surface"><div class="section-heading"><div><h2>Service levels</h2><p>First response and resolution are separate clocks.</p></div></div><div class="panel-body small muted">${resumed||done?'One clock unmeasured.':'Both clocks measured.'} Fixture evaluated 13 Sep 2026, 10:10 am NZST. Waiting status alone is not proof that a clock is paused.</div></section><div class="${filterValue()==='all'?'two-column':'stack'}">${filterValue()!=='resolution'?response:''}${filterValue()!=='response'?resolution:''}</div></div>`;
  }
  function activityPanel() {const events=state.activity.filter(e=>filterValue()==='all'||e[4]===filterValue());return `<section class="surface"><div class="section-heading"><div><h2>Activity</h2><p>Ticket decisions and work events · Newest first</p></div>${badge('Today','neutral','CalendarDays')}</div><div class="panel-body">${events.map(e=>`<div class="activity-row"><time>${e[0]}</time><span class="activity-dot">${icon(e[1])}</span><div><p>${esc(e[2])}</p><small>${esc(e[3])}</small></div></div>`).join('')}</div></section>`;}
  // Proposed operational additions requested during review. Local fixtures only.
  let booking=null, editingTimeId=null;
  const sampleUsers=[
    {id:'maya',name:'Maya Chen',role:'Office coordinator',site:'Harbour Office',email:'maya.chen@example.test',phone:'09 555 0148 ext 214',window:'Available after 12:30 pm today',source:'From Maya’s latest reply'},
    {id:'omar',name:'Omar Patel',role:'Site administrator',site:'Harbour Office',email:'omar.patel@example.test',phone:'09 555 0152 ext 208',window:'Contact availability not recorded',source:'Confirm a suitable contact time'},
    {id:'priya',name:'Priya Shah',role:'Office support',site:'Harbour Office',email:'priya.shah@example.test',phone:'09 555 0163 ext 219',window:'Contact availability not recorded',source:'Confirm a suitable contact time'}
  ];
  state.requesterId='maya';state.affectedId='maya';
