  const modalHead=(title,description,symbol='Info')=>`<div class="dialog-header"><h2 id="dialog-title">${icon(symbol)}${title}</h2><p id="dialog-description">${description}</p><button class="dialog-close" data-action="dialog-close" aria-label="Close dialog">${icon('X')}</button></div>`;
  const modalFoot=(primary='',secondary='Cancel')=>`<div class="dialog-footer">${button(secondary,'dialog-close','','')}<div class="row"><span class="dialog-note">Preview only</span>${primary}</div></div>`;
  function openDialog(type,title,description,body,footer='',width=720) {
    if(!$('dialog').open)returnFocus=document.activeElement;
    dialogType=type;dialogDirty=false;
    $('dialog').className='';$('dialog').style.width=`min(92vw,${width}px)`;$('dialog').style.maxWidth=`min(92vw,${width}px)`;
    $('dialog').innerHTML=modalHead(title,description)+`<div class="dialog-body">${body}</div>`+(footer||modalFoot('', 'Close'));
    if(!$('dialog').open)$('dialog').showModal();
  }
  function closeDialog(force=false) {
    if(dialogDirty&&!force){
      const previous={markup:$('dialog').innerHTML,type:dialogType,width:$('dialog').style.width,values:[...$('dialog').querySelectorAll('input,textarea,select')].map(el=>({id:el.id,value:el.value,checked:el.checked}))};
      openDialog('discard','Discard these changes?','Your unsaved changes in this dialog will be lost. Ticket message drafts are kept.',`<p class="small muted">You can return to the dialog and keep editing.</p>`,modalFoot(button('Discard changes','discard-dialog','','destructive'),'Keep editing'),480);
      $('dialog').querySelector('[data-action="dialog-close"]').dataset.action='restore-dialog';
      $('dialog').querySelector('.dialog-footer [data-action="dialog-close"]').dataset.action='restore-dialog';
      $('dialog')._previous=previous;return;
    }
    dialogDirty=false;dialogType='';$('dialog').close();returnFocus?.isConnected&&returnFocus.focus({preventScroll:true});
  }
  function restoreDialog() {const prev=$('dialog')._previous;if(!prev)return;dialogType=prev.type;dialogDirty=true;$('dialog').style.width=prev.width;$('dialog').style.maxWidth=prev.width;$('dialog').innerHTML=prev.markup;prev.values.forEach(v=>{const el=$(v.id);if(el){el.value=v.value;el.checked=v.checked;}});}
  function requiredField(id,label,value='',help='',placeholder='') {return `<div class="field"><label for="${id}">${label} <span class="req">*</span></label><textarea id="${id}" placeholder="${esc(placeholder)}" required>${esc(value)}</textarea>${help?`<small>${help}</small>`:''}<p class="field-error" id="${id}-error" hidden></p></div>`;}
  function validate(ids) {let valid=true;ids.forEach(id=>{const el=$(id),error=$(id+'-error');if(!el.value.trim()){valid=false;el.setAttribute('aria-invalid','true');error.hidden=false;error.textContent='Enter '+(id==='task-evidence'?'how this task was verified.':'a clear description.');el.setAttribute('aria-describedby',error.id);}else{el.removeAttribute('aria-invalid');error.hidden=true;}});if(!valid)ids.map($).find(el=>!el.value.trim())?.focus();return valid;}
