  function openTask() {openDialog('task','Verify workstation test','Required task · Assigned to Jordan Lee · Workplace IT',`<h3 style="margin-bottom:8px">Verify printing from the requester’s workstation</h3><p class="small muted" style="margin-bottom:20px">Record the actual test and result before marking this task verified complete.</p>${requiredField('task-evidence','Completion evidence',state.taskEvidence,'Do not mark complete until the requester’s test has passed.','For example: Maya printed a one-page test from her workstation at 12:34 pm; the page arrived correctly.')}<label class="dialog-check"><input id="task-confirm" type="checkbox" ${state.taskComplete?'checked':''}>I have checked the evidence and the required task is complete.</label><p class="field-error" id="task-confirm-error" hidden></p>`,modalFoot(button(state.taskComplete?'Update evidence':'Verify completion','verify-task','ClipboardCheck','primary')));}
