    'reset':()=>openDialog('reset','Reset this preview?','All simulated replies, task changes and unsent drafts will be cleared.',`<p class="small muted">The original synthetic ticket will return. Application data is unaffected.</p>`,modalFoot(button('Reset preview','reset-confirm','RotateCcw','destructive'),'Keep reviewing'),480),
    'reset-confirm':()=>{Object.values(state.drafts).forEach(d=>{d.text='';d.files=[];d.time=freshNoteTime(false);});location.reload();}
